using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;
using Microsoft.Win32;
using SoopaDriveTool.Core;
namespace SoopaDriveTool.Windows;
public partial class MainWindow
{
    void DiagnosticActions(ComboBox disk,ComboBox transport)
    {
        var tests=new WrapPanel();foreach(string type in new[]{"short","long","conveyance","abort"})tests.Children.Add(Btn(type=="abort"?"Abort self-test":"Start "+type+" self-test",async()=>{if(disk.SelectedItem is not DiskInfo d)throw new IOException("Select a drive.");await Work("Sending SMART self-test request",async()=>MessageBox.Show(this,await SmartService.SelfTestAsync(d,type,(string)transport.SelectedItem),"Device self-test"));}));
        var temperature=new StackPanel();var history=Btn("Temperature history",()=>{if(disk.SelectedItem is not DiskInfo d)throw new IOException("Select a drive.");string path=System.IO.Path.Combine(Data.Home,"temperatures",d.Identity+".json");var points=File.Exists(path)?JsonSerializer.Deserialize<List<TemperaturePoint>>(File.ReadAllText(path),Data.Json)??[]:[];temperature.Children.Clear();if(points.Count==0){temperature.Children.Add(T("No temperature readings exposed by this device yet.",12,Muted));return;}var canvas=new Canvas{Height=150,Width=800,ClipToBounds=true};double min=points.Min(p=>p.Celsius)-2,max=points.Max(p=>p.Celsius)+2;var line=new Polyline{Stroke=Accent,StrokeThickness=2};for(int i=0;i<points.Count;i++)line.Points.Add(new Point(10+780.0*i/Math.Max(1,points.Count-1),140-130*(points[i].Celsius-min)/(max-min)));canvas.Children.Add(line);temperature.Children.Add(T($"{points.Count} samples · {points.Min(p=>p.Celsius):0.0}–{points.Max(p=>p.Celsius):0.0} °C · Latest {points[^1].Utc:u}",12,Muted));temperature.Children.Add(canvas);temperature.Children.Add(Table(points.TakeLast(100),("UTC","Utc"),("°C","Celsius")));});
        body.Children.Add(Card(Stack(T("Device tests and temperature",19,Ink,true),T("Self-tests run in the drive firmware and may affect performance. The SMART report shows actual completion and errors. Unsupported tests fail explicitly.",12,Muted),tests,history,temperature)));
        var map=new WrapPanel();List<SurfaceBlock>? last=null;var read=Stack(T("Read surface scan",19,Ink,true),T("Reads every region without writing. Red means a read error; amber means a region took more than 500 ms. Timing reflects the complete storage path, including VM and controller delays.",12,Muted),Btn("Scan selected disk",async()=>{if(disk.SelectedItem is not DiskInfo d)throw new IOException("Select a drive.");await RunTaskWithActivity("Reading drive surface",async(p,ct)=>{using var input=DiskAccess.Open(d,false,false);last=await Task.Run(()=>DiskRecovery.SurfaceScanAsync(input,0,d.Size,4*1024*1024,p,ct));map.Children.Clear();int aggregate=Math.Max(1,(last.Count+399)/400);for(int i=0;i<last.Count;i+=aggregate){var slice=last.Skip(i).Take(aggregate).ToList();string status=slice.Any(x=>x.Status=="Read error")?"Read error":slice.Any(x=>x.Status=="Slow")?"Slow":"Readable";map.Children.Add(new Border{Width=24,Height=15,Margin=new Thickness(2),Background=status=="Read error"?B("#D64B58"):status=="Slow"?B("#D89D34"):B("#26AB85"),ToolTip=$"{Data.Size(slice[0].Offset)} · {status} · {slice.Max(x=>x.Milliseconds):0.0} ms"});}});}),map,Btn("Export scan report…",async()=>{if(last==null)throw new IOException("Run a scan first.");var save=new SaveFileDialog{Filter="JSON surface report|*.json",FileName="SoopaDriveTool-surface.json"};if(save.ShowDialog(this)==true)await Data.SaveAsync(save.FileName,last);}));body.Children.Add(Card(read));
        var eraseMethod=Choices("NVMe crypto erase","NVMe block erase");body.Children.Add(Card(Stack(T("Device-native erase",19,Ink,true),T("Destroys the selected data disk through its storage controller. Some firmware/driver combinations reject these commands. Progress may be unavailable. ATA secure erase is available in the recovery environment.",12,Muted),eraseMethod,Btn("Review device erase…",async()=>{if(disk.SelectedItem is not DiskInfo d)throw new IOException("Select a data disk.");if(Prompt("Review controller erase","All data on "+d.Display+" will be destroyed. Type exactly DISK "+d.Number)!= "DISK "+d.Number)return;await RunTaskWithActivity("Controller erase",async(p,ct)=>{string result=await DiagnosticsService.NativeEraseAsync(d,eraseMethod.SelectedIndex==0?"CryptoErase":"BlockErase",p);MessageBox.Show(this,result,"Controller completion");},false);}))));
        var partition=new ComboBox{DisplayMemberPath="Display"};void Update()=>partition.ItemsSource=(disk.SelectedItem as DiskInfo)?.Partitions.Where(x=>!x.Protected).ToList();disk.SelectionChanged+=(_,_)=>Update();Update();var method=Choices("Zero free space","Random / ones / zeros free space");body.Children.Add(Card(Stack(T("Overwrite unused file space",19,Ink,true),T("Creates temporary files in free space and removes only those files afterward. Keeps a 256 MiB reserve. Does not cover filesystem slack, compressed history, snapshots or remapped SSD cells.",12,Muted),partition,method,Btn("Review free-space overwrite…",async()=>{if(disk.SelectedItem is not DiskInfo d||partition.SelectedItem is not PartitionInfo part)throw new IOException("Select a data volume.");if(Prompt("Overwrite free space","Type exactly "+part.Letter+": to overwrite recoverable data in free space.")!=part.Letter+":")return;await RunTaskWithActivity("Free-space overwrite",(p,ct)=>DiagnosticsService.FreeSpaceWipeAsync(d,part,method.SelectedIndex==1,p,ct));}))));
        var topology=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,MaxHeight=300,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};body.Children.Add(Card(Stack(T("Storage topology",19,Ink,true),Btn("Read disks, volumes, pools and virtual disks",async()=>await Work("Reading Windows storage topology",async()=>topology.Text=await DiagnosticsService.TopologyAsync())),topology,Btn("Export topology…",()=>{var save=new SaveFileDialog{Filter="JSON topology|*.json",FileName="SoopaDriveTool-topology.json"};if(save.ShowDialog(this)==true)File.WriteAllText(save.FileName,topology.Text);}))));
    }
}
